@Composable
private fun NativeUiBlockListEditor(
    label: String,
    parentPath: String,
    parentLabel: String,
    blocks: List<NativeUiBlockDraft>,
    availablePages: List<NativeUiPageDraft>,
    selectedPath: String?,
    onSelectedPathChange: (String) -> Unit,
    canEdit: Boolean,
    theme: MaterialThemePalette,
    onChange: (List<NativeUiBlockDraft>) -> Unit,
) {
    var nextBlockType by remember(parentPath) { mutableStateOf(NativeUiBlockType.Text) }

    Div(
        attrs = {
            style {
                display(DisplayStyle.Flex)
                flexDirection(FlexDirection.Column)
                gap(14.px)
            }
        }
    ) {
        P(
            attrs = {
                style {
                    margin(0.px)
                    property("font-size", "0.82rem")
                    property("font-weight", "700")
                    property("letter-spacing", "0.06em")
                    property("text-transform", "uppercase")
                    property("color", theme.onSurfaceVariant)
                }
            }
        ) {
            Text(label)
        }

        if (blocks.isEmpty()) {
            P(
                attrs = {
                    style {
                        margin(0.px)
                        padding(14.px)
                        borderRadius(16.px)
                        property("background", theme.surfaceContainerHighest)
                        property("border", "1px dashed ${theme.outlineVariant}")
                        property("color", theme.onSurfaceVariant)
                        property("line-height", "1.5")
                    }
                }
            ) {
                Text("No content blocks yet. Add one below.")
            }
        }

        blocks.forEachIndexed { index, block ->
            BlockEditorCard(
                block = block,
                pathKey = "$parentPath/block:$index",
                contextLabel = "$parentLabel / ${block.type.label} ${index + 1}",
                index = index,
                totalBlocks = blocks.size,
                availablePages = availablePages,
                selectedPath = selectedPath,
                onSelectedPathChange = onSelectedPathChange,
                canEdit = canEdit,
                theme = theme,
                onChange = { nextBlock ->
                    onChange(blocks.replaceAt(index, nextBlock))
                },
                onMoveUp = { onChange(blocks.move(fromIndex = index, toIndex = index - 1)) },
                onMoveDown = { onChange(blocks.move(fromIndex = index, toIndex = index + 1)) },
                onRemove = { onChange(blocks.removeAt(index)) },
            )
        }

        FieldRow {
            StringSelectField(
                theme = theme,
                label = "Block Type",
                value = nextBlockType.wireValue,
                options = NativeUiBlockType.entries.map { it.wireValue to it.label },
                emptyLabel = "Choose block type",
                isDisabled = !canEdit,
                onValueChange = { selected ->
                    NativeUiBlockType.entries.firstOrNull { it.wireValue == selected }?.let { nextBlockType = it }
                },
            )
            ActionButton(
                label = "Add Block",
                onClick = { if (canEdit) onChange(blocks + defaultBlockDraft(nextBlockType)) },
                theme = theme,
                isDisabled = !canEdit,
                isPrimary = false,
            )
        }
    }
}

@Composable
private fun BlockEditorCard(
    block: NativeUiBlockDraft,
    pathKey: String,
    contextLabel: String,
    index: Int,
    totalBlocks: Int,
    availablePages: List<NativeUiPageDraft>,
    selectedPath: String?,
    onSelectedPathChange: (String) -> Unit,
    canEdit: Boolean,
    theme: MaterialThemePalette,
    onChange: (NativeUiBlockDraft) -> Unit,
    onMoveUp: () -> Unit,
    onMoveDown: () -> Unit,
    onRemove: () -> Unit,
) {
    val isSelected = selectedPath == pathKey
    val hasSelectedDescendant = selectedPath?.startsWith("$pathKey/") == true
    var isExpanded by remember(pathKey) {
        mutableStateOf(pathKey.count { it == '/' } <= 1)
    }
    EditorPanel(
        title = blockDisplayTitle(block),
        description = "$contextLabel. Block ${index + 1} of $totalBlocks.",
        theme = theme,
        isEmphasized = isSelected || hasSelectedDescendant,
        actions = {
            Div(
                attrs = {
                    style {
                        display(DisplayStyle.Flex)
                        gap(8.px)
                        property("flex-wrap", "wrap")
                    }
                }
            ) {
                ActionButton(
                    label = if (isSelected) "Focused" else "Focus",
                    onClick = { onSelectedPathChange(pathKey) },
                    theme = theme,
                    isDisabled = isSelected,
                    isPrimary = false,
                )
                ActionButton(
                    label = if (isExpanded || hasSelectedDescendant) "Collapse" else "Expand",
                    onClick = { isExpanded = !isExpanded },
                    theme = theme,
                    isDisabled = false,
                    isPrimary = false,
                )
                ActionButton(
                    label = "Move Up",
                    onClick = onMoveUp,
                    theme = theme,
                    isDisabled = !canEdit || index == 0,
                    isPrimary = false,
                )
                ActionButton(
                    label = "Move Down",
                    onClick = onMoveDown,
                    theme = theme,
                    isDisabled = !canEdit || index == totalBlocks - 1,
                    isPrimary = false,
                )
                ActionButton(
                    label = "Remove",
                    onClick = onRemove,
                    theme = theme,
                    isDisabled = !canEdit,
                    isPrimary = false,
                )
            }
        },
    ) {
        P(
            attrs = {
                style {
                    margin(0.px)
                    property("font-size", "0.82rem")
                    property("color", theme.onSurfaceVariant)
                    property("line-height", "1.45")
                }
            }
        ) {
            Text(blockMeta(block))
        }

        if (!(isExpanded || hasSelectedDescendant)) {
            return@EditorPanel
        }

        TextField(
            theme = theme,
            label = "Block ID",
            value = block.id,
            placeholder = "optional-block-id",
            onValueChange = { nextId -> if (canEdit) onChange(updateBlockId(block, nextId)) },
        )

        when (block) {
            is NativeUiTextBlockDraft -> {
                FieldRow {
                    TextField(
                        theme = theme,
                        label = "Text",
                        value = block.text,
                        placeholder = "Enter text",
                        onValueChange = { nextText -> if (canEdit) onChange(block.copy(text = nextText)) },
                    )
                    StringSelectField(
                        theme = theme,
                        label = "Variant",
                        value = block.variant.wireValue,
                        options = NativeUiTextVariant.entries.map { it.wireValue to it.label },
                        isDisabled = !canEdit,
                        onValueChange = { nextVariant ->
                            if (canEdit) {
                                onChange(
                                    block.copy(
                                        variant = NativeUiTextVariant.entries.first { it.wireValue == nextVariant }
                                    )
                                )
                            }
                        },
                    )
                }
                ColorRoleField(
                    theme = theme,
                    label = "Color Role",
                    value = block.colorRole,
                    canEdit = canEdit,
                    onValueChange = { nextRole -> onChange(block.copy(colorRole = nextRole)) },
                )
            }

            is NativeUiImageBlockDraft -> {
                FieldRow {
                    TextField(
                        theme = theme,
                        label = "Image URL",
                        value = block.url,
                        placeholder = "https://example.com/image.png",
                        onValueChange = { nextUrl -> if (canEdit) onChange(block.copy(url = nextUrl)) },
                    )
                    TextField(
                        theme = theme,
                        label = "Aspect Ratio",
                        value = block.aspectRatio,
                        placeholder = "1.777",
                        inputTypeOverride = "number",
                        step = "0.1",
                        onValueChange = { nextRatio -> if (canEdit) onChange(block.copy(aspectRatio = nextRatio)) },
                    )
                }
                TextField(
                    theme = theme,
                    label = "Content Description",
                    value = block.contentDescription,
                    placeholder = "Accessible description",
                    onValueChange = { nextDescription -> if (canEdit) onChange(block.copy(contentDescription = nextDescription)) },
                )
            }

            is NativeUiButtonBlockDraft -> {
                FieldRow {
                    TextField(
                        theme = theme,
                        label = "Label",
                        value = block.label,
                        placeholder = "Primary action",
                        onValueChange = { nextLabel -> if (canEdit) onChange(block.copy(label = nextLabel)) },
                    )
                    StringSelectField(
                        theme = theme,
                        label = "Style",
                        value = block.style.wireValue,
                        options = NativeUiButtonStyleDraft.entries.map { it.wireValue to it.label },
                        isDisabled = !canEdit,
                        onValueChange = { nextStyle ->
