                }
            ) {
                Text("Carousel blocks need at least one image item.")
            }
        }

        items.forEachIndexed { index, item ->
            val itemPath = "$pathKey/item:$index"
            val isSelected = selectedPath == itemPath
            var isExpanded by remember(itemPath) { mutableStateOf(index == 0) }
            EditorPanel(
                title = item.title.ifBlank { "Carousel Item ${index + 1}" },
                description = "$parentLabel / Carousel Item ${index + 1}. Add the image, text, and link for this slide.",
                theme = theme,
                isEmphasized = isSelected,
