                            label = if (isExpanded) "Collapse" else "Expand",
                            onClick = { isExpanded = !isExpanded },
                            theme = theme,
                            isDisabled = false,
                            isPrimary = false,
                        )
                        ActionButton(
                            label = "Remove",
                            onClick = { onChange(items.removeAt(index)) },
                            theme = theme,
                            isDisabled = !canEdit || items.size <= 1,
                            isPrimary = false,
                        )
                    }
                },
            ) {
                if (!isExpanded) {
                    return@EditorPanel
                }

                TextField(
                    theme = theme,
                    label = "Image URL",
                    value = item.imageUrl,
                    placeholder = "https://example.com/highlight.jpg",
                    onValueChange = { nextUrl ->
                        if (canEdit) onChange(items.replaceAt(index, item.copy(imageUrl = nextUrl)))
                    },
                )
                FieldRow {
                    TextField(
                        theme = theme,
                        label = "Title",
                        value = item.title,
                        placeholder = "Live from the student section",
