@Composable
private fun PreviewBlockNode(
    block: NativeUiBlockDraft,
    pathKey: String,
    selectedPath: String?,
    theme: MaterialThemePalette,
    onSelectedPathChange: (String) -> Unit,
) {
    val isSelected = selectedPath == pathKey
    val hasSelectedDescendant = selectedPath?.startsWith("$pathKey/") == true

    Div(
        attrs = {
            onClick {
                it.stopPropagation()
                onSelectedPathChange(pathKey)
            }
            style {
                display(DisplayStyle.Flex)
                flexDirection(FlexDirection.Column)
                gap(10.px)
                padding(12.px)
                borderRadius(14.px)
                property("cursor", "pointer")
                property("background", if (isSelected) theme.primaryContainer else theme.surface)
                property("border", "1px solid ${if (isSelected || hasSelectedDescendant) theme.primary else theme.outlineVariant}")
            }
        }
    ) {
        P(
            attrs = {
                style {
                    margin(0.px)
                    property("font-size", "0.72rem")
                    property("font-weight", "700")
                    property("letter-spacing", "0.08em")
                    property("text-transform", "uppercase")
                    property("color", if (isSelected) theme.onPrimaryContainer else theme.onSurfaceVariant)
                }
            }
        ) {
            Text(block.type.label)
        }
        P(
            attrs = {
                style {
                    margin(0.px)
                    property("font-size", "0.95rem")
                    property("font-weight", "700")
                    property("color", if (isSelected) theme.onPrimaryContainer else theme.onSurface)
                }
            }
        ) {
            Text(blockDisplayTitle(block))
        }
        P(
            attrs = {
                style {
                    margin(0.px)
                    property("font-size", "0.84rem")
                    property("line-height", "1.5")
                    property("color", if (isSelected) theme.onPrimaryContainer else theme.onSurfaceVariant)
                }
            }
        ) {
            Text(blockMeta(block))
        }

        when (block) {
            is NativeUiSectionBlockDraft -> {
                block.blocks.forEachIndexed { index, child ->
                    PreviewBlockNode(
                        block = child,
                        pathKey = "$pathKey/block:$index",
                        selectedPath = selectedPath,
                        theme = theme,
                        onSelectedPathChange = onSelectedPathChange,
                    )
                }
            }

            is NativeUiCardBlockDraft -> {
                block.blocks.forEachIndexed { index, child ->
                    PreviewBlockNode(
                        block = child,
                        pathKey = "$pathKey/block:$index",
                        selectedPath = selectedPath,
                        theme = theme,
                        onSelectedPathChange = onSelectedPathChange,
                    )
                }
            }

            is NativeUiCarouselBlockDraft -> {
                block.items.forEachIndexed { index, item ->
                    PreviewLeafNode(
                        eyebrow = "Carousel Item",
                        title = item.title.ifBlank { "Item ${index + 1}" },
                        meta = item.subtitle.ifBlank { item.imageUrl.ifBlank { "No image URL yet." } },
                        pathKey = "$pathKey/item:$index",
                        selectedPath = selectedPath,
                        theme = theme,
                        onSelectedPathChange = onSelectedPathChange,
                    )
                }
            }

            is NativeUiListBlockDraft -> {
                block.items.forEachIndexed { index, item ->
                    PreviewLeafNode(
                        eyebrow = "List Item",
                        title = item.title.ifBlank { "Item ${index + 1}" },
                        meta = item.subtitle.ifBlank { item.overline.ifBlank { "No subtitle yet." } },
                        pathKey = "$pathKey/item:$index",
                        selectedPath = selectedPath,
                        theme = theme,
                        onSelectedPathChange = onSelectedPathChange,
                    )
                }
            }

            else -> Unit
        }
    }
}

