private fun buildEditorOutlineEntries(page: NativeUiPageDraft): List<EditorOutlineEntry> {
    val pageLabel = page.title.ifBlank { humanizeRouteId(page.id) }
    return buildList {
        page.blocks.forEachIndexed { index, block ->
            addBlockOutlineEntry(
                pathKey = "page:${page.id}/block:$index",
                depth = 0,
                breadcrumb = "$pageLabel / ${block.type.label} ${index + 1}",
                block = block,
            )
        }
    }
}

private fun MutableList<EditorOutlineEntry>.addBlockOutlineEntry(
    pathKey: String,
    depth: Int,
    breadcrumb: String,
    block: NativeUiBlockDraft,
) {
    add(
        EditorOutlineEntry(
            pathKey = pathKey,
            depth = depth,
            eyebrow = block.type.label,
            title = blockDisplayTitle(block),
            meta = blockMeta(block),
            breadcrumb = breadcrumb,
        )
    )

    when (block) {
        is NativeUiSectionBlockDraft -> {
            block.blocks.forEachIndexed { index, child ->
                addBlockOutlineEntry(
                    pathKey = "$pathKey/block:$index",
                    depth = depth + 1,
                    breadcrumb = "$breadcrumb / ${child.type.label} ${index + 1}",
                    block = child,
                )
            }
        }

        is NativeUiCardBlockDraft -> {
            block.blocks.forEachIndexed { index, child ->
                addBlockOutlineEntry(
                    pathKey = "$pathKey/block:$index",
                    depth = depth + 1,
                    breadcrumb = "$breadcrumb / ${child.type.label} ${index + 1}",
                    block = child,
                )
            }
        }

        is NativeUiCarouselBlockDraft -> {
            block.items.forEachIndexed { index, item ->
                add(
                    EditorOutlineEntry(
                        pathKey = "$pathKey/item:$index",
                        depth = depth + 1,
                        eyebrow = "Carousel Item",
                        title = item.title.ifBlank { "Item ${index + 1}" },
                        meta = item.subtitle.ifBlank { item.imageUrl.ifBlank { "No image URL yet." } },
                        breadcrumb = "$breadcrumb / Carousel Item ${index + 1}",
                    )
                )
            }
        }

        is NativeUiListBlockDraft -> {
            block.items.forEachIndexed { index, item ->
                add(
                    EditorOutlineEntry(
                        pathKey = "$pathKey/item:$index",
                        depth = depth + 1,
                        eyebrow = "List Item",
                        title = item.title.ifBlank { "Item ${index + 1}" },
                        meta = item.subtitle.ifBlank { item.overline.ifBlank { "No subtitle yet." } },
                        breadcrumb = "$breadcrumb / List Item ${index + 1}",
                    )
                )
            }
        }

        else -> Unit
    }
}

private fun nativeUiPageKindLabel(
    page: NativeUiPageDraft,
    rootPageId: String,
    requiredTabRouteIds: List<String>,
): String =
    when {
        page.id == rootPageId -> "Root page"
        page.id in requiredTabRouteIds -> "Tab page"
        else -> "Subpage"
    }

private fun blockDisplayTitle(block: NativeUiBlockDraft): String =
    when (block) {
        is NativeUiTextBlockDraft -> block.text.ifBlank { "Text Block" }
        is NativeUiImageBlockDraft -> block.contentDescription.ifBlank { block.url.ifBlank { "Image Block" } }
        is NativeUiButtonBlockDraft -> block.label.ifBlank { "Button Block" }
        is NativeUiSpacerBlockDraft -> "Spacer"
        is NativeUiSectionBlockDraft -> block.title.ifBlank { "Section" }
        is NativeUiCardBlockDraft -> block.title.ifBlank { "Card" }
        is NativeUiCarouselBlockDraft -> "Carousel"
        is NativeUiListBlockDraft -> "List"
        is NativeUiEventCardBlockDraft -> block.title.ifBlank { "Event Card" }
        is NativeUiTicketCardBlockDraft -> block.title.ifBlank { "Ticket Card" }
    }

private fun blockMeta(block: NativeUiBlockDraft): String =
    when (block) {
        is NativeUiTextBlockDraft -> "${block.variant.label} text."
        is NativeUiImageBlockDraft -> if (block.url.isBlank()) "No image URL yet." else block.url
        is NativeUiButtonBlockDraft -> if (block.action.type == NativeUiActionType.None) "No action assigned yet." else "Action: ${block.action.type.label}."
        is NativeUiSpacerBlockDraft -> "${block.heightDp}dp spacing."
        is NativeUiSectionBlockDraft -> "${block.blocks.size} nested block${if (block.blocks.size == 1) "" else "s"}."
        is NativeUiCardBlockDraft -> "${block.blocks.size} nested block${if (block.blocks.size == 1) "" else "s"} plus card content."
        is NativeUiCarouselBlockDraft -> "${block.items.size} carousel item${if (block.items.size == 1) "" else "s"}."
        is NativeUiListBlockDraft -> "${block.items.size} list item${if (block.items.size == 1) "" else "s"}."
        is NativeUiEventCardBlockDraft -> block.subtitle.ifBlank { "Event card content." }
        is NativeUiTicketCardBlockDraft -> block.status.ifBlank { "Ticket card content." }
    }

private fun updateBlockId(block: NativeUiBlockDraft, nextId: String): NativeUiBlockDraft =
    when (block) {
        is NativeUiTextBlockDraft -> block.copy(id = nextId)
        is NativeUiImageBlockDraft -> block.copy(id = nextId)
        is NativeUiButtonBlockDraft -> block.copy(id = nextId)
        is NativeUiSpacerBlockDraft -> block.copy(id = nextId)
        is NativeUiSectionBlockDraft -> block.copy(id = nextId)
        is NativeUiCardBlockDraft -> block.copy(id = nextId)
        is NativeUiCarouselBlockDraft -> block.copy(id = nextId)
        is NativeUiListBlockDraft -> block.copy(id = nextId)
        is NativeUiEventCardBlockDraft -> block.copy(id = nextId)
        is NativeUiTicketCardBlockDraft -> block.copy(id = nextId)
    }

private fun defaultBlockDraft(type: NativeUiBlockType): NativeUiBlockDraft =
    when (type) {
        NativeUiBlockType.Text -> NativeUiTextBlockDraft(text = "New text block")
        NativeUiBlockType.Image -> NativeUiImageBlockDraft(url = "https://example.com/image.png")
        NativeUiBlockType.Button -> NativeUiButtonBlockDraft(label = "New Button")
        NativeUiBlockType.Spacer -> NativeUiSpacerBlockDraft()
        NativeUiBlockType.Section -> NativeUiSectionBlockDraft(title = "Section Title")
        NativeUiBlockType.Card -> NativeUiCardBlockDraft(title = "Card Title")
        NativeUiBlockType.Carousel -> NativeUiCarouselBlockDraft(
            items = listOf(
                NativeUiCarouselItemDraft(
                    imageUrl = "https://example.com/highlight.jpg",
                    title = "New highlight",
                )
            )
        )
        NativeUiBlockType.List -> NativeUiListBlockDraft(items = listOf(NativeUiListItemDraft(title = "New item")))
        NativeUiBlockType.EventCard -> NativeUiEventCardBlockDraft(title = "Event Title")
        NativeUiBlockType.TicketCard -> NativeUiTicketCardBlockDraft(title = "Ticket Title")
